style.css:
@-moz-document domain("downloads.khinsider.com") {
/* ============================================================
     KHInsider Dark
     The KHInsider archive (downloads.khinsider.com) is a classic
     server-rendered site with hardcoded light colors and no CSS
     custom properties, so the theme overrides per element: the
     two-column shell, the beveled sidebar module heads, the song
     /album-list tables (tan headers), the HTML5 audio player bar,
     search results, the comment threads and the legacy forms.
     Semantic reds (donate / attention) are preserved; the player
     progress + comment CTA keep a tuned, readable accent.
     ============================================================ */

  :root { color-scheme: dark !important; }

  /* ---- Base shell ---- */
  html, body {
    background-color: #14181d !important;
    background-image: none !important;
    color: #e6edf3 !important;
  }
  #container { background-color: #14181d !important; border-color: #262c33 !important; }
  #rightColumn { background-color: #14181d !important; }
  #pageContent { background-color: #14181d !important; color: #e6edf3 !important; }
  #leftColumn { background-color: #1c2128 !important; }

  /* Soften the hard light borders the layout draws between columns */
  #pageContent, #leftColumn, #rightColumn,
  #pageContent div, #homepagePopularSeries, #homepageLatestSoundtracks {
    border-color: #262c33 !important;
  }

  /* ---- Sidebar logo + navigation ---- */
  #leftColumn h1, #leftColumn h1 a { color: #e6edf3 !important; }

  /* Beveled module heads ship a light gradient image — flatten to dark */
  #leftColumn h3 {
    background-color: #0d1117 !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }
  #leftColumn ul li a { color: #c4cdd6 !important; }
  #leftColumn ul li a:hover { color: #9bd4ff !important; }
  /* raw red star/heart accent icons -> softened red, more legible on dark */
  #leftColumn .material-icons { color: #ff7b72 !important; }

  /* ---- Headings + body text ---- */
  h1, h2, h3, h4, h5 { color: #e6edf3 !important; }
  #pageContent p,
  #pageContent li,
  #pageContent b,
  #pageContent span,
  #pageContent div,
  #homepageText,
  #homepageText p { color: #c4cdd6 !important; }

  /* ---- Links ---- */
  #pageContent a { color: #5fb0e6 !important; }
  #pageContent a:hover { color: #9bd4ff !important; }
  /* keep attention/donate reds legible without dumping raw #f00 */
  #pageContent a[href*="donat"],
  #pageContent font[color="red"],
  #pageContent .albumMassDownload a { color: #ff7b72 !important; }

  /* ---- Tables: album list, song list, search results ---- */
  #songlist, .albumList, .requestList, #pageContent table {
    background-color: transparent !important;
    border-color: #2d333b !important;
  }
  /* tan (#cccc99) header + total rows -> elevated dark */
  #songlist th, .albumList th, .requestList th,
  #songlist tr.header td, #songlist .clickable-row.collapsed,
  #songlist #songlist_footer td, #songlist tr#songlist_footer th {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  #songlist td, .albumList td, .requestList td {
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }
  #songlist tr td a, .albumList td a, .requestList td a { color: #5fb0e6 !important; }
  /* zebra + hover */
  #songlist tr:hover td,
  .albumList tr:hover td,
  .requestList tr:hover td { background-color: #1c2128 !important; }
  /* the song "Total:" footer row */
  #songlist tr:last-child td,
  #songlist tr:last-child th { background-color: #1c2128 !important; color: #e6edf3 !important; }
  /* table download / add-to-playlist glyphs (black originals) */
  #songlist .material-icons,
  .playlistDownloadSong .material-icons,
  .playlistAddTo .material-icons,
  .playTrack .material-icons { color: #c4cdd6 !important; }
  #songlist .material-icons:hover,
  .playlistDownloadSong .material-icons:hover,
  .playlistAddTo .material-icons:hover { color: #9bd4ff !important; }

  /* ---- Album art ---- */
  .albumImage img, .albumImage a { border-color: #2d333b !important; }

  /* ---- Native <audio> element (per-song download page) ----
     The song download page uses a real HTML5 <audio controls> that
     renders as a stark white default-Chrome pill — force its UA
     controls dark. (The custom .audioplayer widget is themed below.) */
  audio {
    color-scheme: dark !important;
    background-color: #1c2128 !important;
    border-radius: 8px !important;
  }

  /* ---- HTML5 audio player (custom widget) ---- */
  .audioplayer {
    background-color: #0d1117 !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .audioplayer * { color: #e6edf3 !important; border-color: #2d333b !important; }
  .audioplayerTimeCurrent, .audioplayerTimeDuration { color: #c4cdd6 !important; }
  .audioplayer .material-icons { color: #e6edf3 !important; }
  /* progress track + played accent */
  .audioplayerBar {
    background-color: #1c2128 !important;
    background-image: none !important;
  }
  .audioplayerBarLoaded {
    background-color: #2d333b !important;
    background-image: none !important;
  }
  .audioplayerBarPlayed {
    background-color: #5fb0e6 !important;
    background-image: none !important;
  }
  /* volume popup + level */
  .audioplayerVolumeBar, .audioplayerVolumeBarPopup {
    background-color: #1c2128 !important;
    background-image: none !important;
    border-color: #2d333b !important;
  }
  .audioplayerVolumeBarLevel {
    background-color: #5fb0e6 !important;
    background-image: none !important;
  }

  /* ---- Comments ---- */
  #news_comments, .comment_wrap { background-color: transparent !important; }
  .comment_message {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .comment_message a { color: #5fb0e6 !important; }
  /* speech-bubble pointer is a white raster triangle — tint it to the bubble color */
  .comment_graphic { filter: brightness(0.14) !important; }
  .quote {
    background-color: #161d27 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .comments_headinggraphic, .comments_headinggraphic2 { color: #e6edf3 !important; }
  /* "+ Comment" CTA: original light-blue button -> tuned dark-blue, white text */
  .reply_to_comment a {
    background-color: #1f6feb !important;
    color: #ffffff !important;
  }
  #pageContent .reply_to_comment a font,
  #pageContent .reply_to_comment a span { color: #ffffff !important; }

  /* ---- Forms ---- */
  input[type="text"], input[type="search"], input[type="password"],
  input[type="email"], textarea, select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }
  input[type="text"]::placeholder, textarea::placeholder { color: #8b949e !important; }
  input[type="submit"], input[type="button"], button {
    background-color: #1c2128 !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }
  input[type="submit"]:hover, input[type="button"]:hover, button:hover {
    background-color: #262c33 !important;
  }

  /* ---- Cookie consent banner ---- */
  .cookieinfo {
    background-color: #0d1117 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .cookieinfo a { color: #5fb0e6 !important; }
  .cookieinfo-close { color: #14181d !important; }

  /* ---- Scrollbar ---- */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: #14181d; }
  ::-webkit-scrollbar-thumb { background: #2d333b; border-radius: 6px; }
  ::-webkit-scrollbar-thumb:hover { background: #3a4250; }
}
